use std::{collections::{BTreeMap,BTreeSet},fs,path::Path};use serde_json::{json,Value};use sha2::{Digest,Sha256};use zopro_bn254::Fr;type Word=[u64;4];
include!("group-function.rs");
fn token(seed:&mut u64)->Fr{let mut b=[0;32];for c in b.chunks_mut(8){*seed^=*seed<<13;*seed^=*seed>>7;*seed^=*seed<<17;c.copy_from_slice(&seed.to_le_bytes());}Fr::from_le_bytes_mod_order(&b)}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/g2-balanced-count175");let pins=read(r.join("pins-final.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}assert_eq!(read(r.join("runs-final/result.json"))["status"],"complete");let mut rows=vec![];for shape in["1x2","2x2"]{let p=format!("/home/ubuntu/src/zopro-perf-work/g2-queue-scan175/inputs/{shape}.b2q");let b=fs::read(&p).unwrap();let n=u64::from_le_bytes(b[8..16].try_into().unwrap())as usize;let words=b[16+128*n..].chunks_exact(32).map(|b|core::array::from_fn(|i|u64::from_le_bytes(b[i*8..i*8+8].try_into().unwrap()))).collect::<Vec<Word>>();let grouped=groups(&words);if let Some((values,classes))=&grouped{assert_eq!(classes.len(),words.len());for(w,&c)in words.iter().zip(classes){if c==usize::MAX{assert_eq!(*w,[0;4]);}else{assert_eq!(*w,values[c]);}}for tag in 0..2{let mut seed=0x62616c616e636564u64^tag;let tokens=(0..n).map(|_|token(&mut seed)).collect::<Vec<_>>();let original=words.iter().zip(&tokens).fold(Fr::ZERO,|a,(s,p)|a+Fr::from_le_bytes_mod_order(&s.into_iter().flat_map(|w|w.to_le_bytes()).collect::<Vec<_>>())* *p);let mut class_tokens=vec![Fr::ZERO;values.len()];for(&c,&v)in classes.iter().zip(&tokens){if c!=usize::MAX{class_tokens[c]+=v;}}let regrouped=values.iter().zip(class_tokens).fold(Fr::ZERO,|a,(s,p)|a+Fr::from_le_bytes_mod_order(&s.into_iter().flat_map(|w|w.to_le_bytes()).collect::<Vec<_>>())*p);assert_eq!(original,regrouped);}}rows.push(json!({"shape":shape,"input_rows":n,"grouping_admitted":grouped.is_some(),"every_original_class_value_checked":true,"both_token_dot_products_equal_original_input":true}));}
let logs=fs::read_to_string(r.join("runs-final/count-real-inputs/stdout.log")).unwrap();let mut modeled=vec![];for l in logs.lines(){if let Some(s)=l.strip_prefix("ROW "){let v:Value=serde_json::from_str(s).unwrap();assert_eq!(v["both_weighted_whole_sums_match_original_scalar_dot_product"],true);assert_eq!(v["balanced_bucket_slots_per_part"],17408);assert_eq!(v["original_bucket_slots_per_part"],20544);let c=&v["balanced_all_ordinary"];assert!(c["max_batch"].as_u64().unwrap()<=200);assert!(c["max_queue"].as_u64().unwrap()<200);assert_eq!(v["balanced_ordinary_jobs"],22);modeled.push(v);}}assert_eq!(modeled.len(),2);let complete:Value=serde_json::from_str(logs.lines().find_map(|l|l.strip_prefix("COMPLETE ")).unwrap()).unwrap();let a=json!({"complete":true,"necessary_opportunity_gate":true,"rows":modeled,"grouping_review":rows,"capture_or_performance_claim":false,"production_changed":false,"new_model_tests":2,"new_solver_calls":0,"SDK_requests":0,"new_independent_exports":0,"proof_ledger":23971,"source_pins_verified":pins.as_object().unwrap().len(),"count_workflow":complete,"goal_achieved":false});fs::write(r.join("analysis.json"),serde_json::to_vec_pretty(&a).unwrap()).unwrap();println!("Verified{}sourcepins,2newgeometrytests,2realpopulations,allgroupvalues+2dotproducts;0newsolve/proof",pins.as_object().unwrap().len());}
